int main() {
    int N, A, B;
    scanf("%d %d %d", &N, &A, &B);

    if ((long long)A * B < N) {
        printf("-1\n");
        return 0;
    }

    // Construct permutation with LIS=A, LDS=B, length=N
    // Use B blocks, each block has at most A elements in decreasing order
    // Block k (0-indexed): elements are placed decreasingly
    // The values across blocks increase
    // We fill: block 0 gets values 1..size0, block 1 gets size0+1..size0+size1, etc.
    // Each block written in decreasing order
    // This gives LDS = number of blocks = B (one from each block decreasing)
    // LIS = max block size = A

    int *seq = (int*)malloc(N * sizeof(int));
    int idx = 0;
    int val = 1;

    for (int b = 0; b < B; b++) {
        // Determine size of this block
        int remaining_blocks = B - b;
        int remaining_vals = N - val + 1;
        // We want each block to have at most A elements
        // Distribute: give A to each block if possible
        int block_size = A;
        if (remaining_vals < block_size * remaining_blocks) {
            // Give ceil(remaining_vals / remaining_blocks) but cap at A
            block_size = (remaining_vals + remaining_blocks - 1) / remaining_blocks;
            if (block_size > A) block_size = A;
        }
        // Actually just: block_size = min(A, remaining_vals - (remaining_blocks-1))
        // Ensure remaining blocks each get at least 1
        if (remaining_vals - block_size < remaining_blocks - 1)
            block_size = remaining_vals - (remaining_blocks - 1);
        if (block_size <= 0) block_size = 1;
        if (block_size > A) block_size = A;

        // Write block in decreasing order
        for (int j = block_size - 1; j >= 0; j--) {
            seq[idx++] = val + j;
        }
        val += block_size;
        if (val > N) break;
    }

    for (int i = 0; i < N; i++) printf("%d%c", seq[i], i==N-1?'\n':' ');
    free(seq);
    return 0;
}

