int main(void) {
    long long N, A, B;
    if (scanf("%lld %lld %lld", &N, &A, &B) != 3) return 0;

    /* Existence condition:
       There exists a permutation of 1..N with
       LIS = A and LDS = B iff
         A + B - 1 <= N <= A * B
    */
    if (N < A + B - 1 || N > A * B) {
        printf("-1\n");
        return 0;
    }

    /* Construct block sizes:
       Number of blocks = A.
       Each block is decreasing; blocks are arranged so all values in earlier
       blocks are smaller than all values in later blocks.
       Then LIS = number of blocks = A, and LDS = max block size = B
       if we choose sizes appropriately.

       Let sizes be s[0..A-1], each >= 1, each <= B, sum = N,
       and at least one size = B.
       Start with all 1's, distribute remaining N-A items, ensuring one block reaches B.
    */
    long long *s = (long long *)malloc(sizeof(long long) * (size_t)A);
    if (!s) return 0;

    for (long long i = 0; i < A; i++) s[i] = 1;

    long long rem = N - A;

    /* Make first block size B */
    long long add = B - 1;
    s[0] += add;
    rem -= add;

    /* Distribute the rest, each block up to size B */
    for (long long i = 1; i < A && rem > 0; i++) {
        long long can = B - 1;
        if (can > rem) can = rem;
        s[i] += can;
        rem -= can;
    }

    /* Output permutation:
       For block sizes s[i], assign consecutive values and print each block reversed.
    */
    long long cur = 1;
    int first = 1;
    for (long long i = 0; i < A; i++) {
        long long start = cur;
        long long end = cur + s[i] - 1;
        for (long long x = end; x >= start; x--) {
            if (!first) printf(" ");
            first = 0;
            printf("%lld", x);
        }
        cur = end + 1;
    }
    printf("\n");

    free(s);
    return 0;
}

