#include <bits/stdc++.h>
using namespace std;

/*
We need a permutation of 1..N whose
- LIS length = A
- LDS length = B

Construction:
Partition the permutation into B contiguous blocks.
Inside each block, numbers are arranged in decreasing order.
Across blocks, all numbers in later blocks are larger than all numbers in earlier blocks.

Then:
- Since each block is decreasing, an increasing subsequence can take at most 1 element from each block.
  Because values strictly increase from block to block, we can take 1 from every block used.
  So LIS = number of blocks = B? Wait, if we use B blocks, LIS = B.

To get LIS = A and LDS = B, instead partition into A blocks, each decreasing.
Then:
- LIS = A
- LDS = max block size

So we need A blocks, positive sizes, summing to N, with maximum size exactly B.
This is possible iff:
  minimum sum with max size B present: A-1 + B
  maximum sum with each size <= B: A*B
Thus:
  A + B - 1 <= N <= A*B

Construction of block sizes:
- Start with all 1's: sum = A
- Need extra = N - A
- Put as much as possible into the first block up to size B, ensuring one block reaches B if possible.
Simpler greedy:
  for i=0..A-1:
    size[i] = 1
  extra = N - A
  for i=0..A-1:
    add = min(extra, B - 1)
    size[i] += add
    extra -= add

This gives sizes in [1,B], sum N.
Condition N >= A+B-1 guarantees at least one block becomes size B, so LDS = B.

Then assign consecutive increasing values to each block, but output each block reversed.
Example block size s with current starting value cur:
 values cur..cur+s-1, output in reverse.

This yields a permutation with LIS=A and LDS=B.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, A, B;
    cin >> N >> A >> B;

    if (!(A + B - 1 <= N && N <= A * B)) {
        cout << -1 << '\n';
        return 0;
    }

    vector<int> sz((int)A, 1);
    long long extra = N - A;

    for (int i = 0; i < A; ++i) {
        long long add = min(extra, B - 1);
        sz[i] += (int)add;
        extra -= add;
    }

    vector<int> ans;
    ans.reserve((int)N);

    int cur = 1;
    for (int s : sz) {
        for (int x = cur + s - 1; x >= cur; --x) ans.push_back(x);
        cur += s;
    }

    for (int i = 0; i < (int)ans.size(); ++i) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}

