import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int A = fs.nextInt();
        int B = fs.nextInt();

        // Necessary and sufficient condition:
        // There exists a permutation of size N with LIS = A and LDS = B
        // iff A + B - 1 <= N <= A * B.
        if (N < A + B - 1 || N > (long) A * B) {
            System.out.println(-1);
            return;
        }

        // Construct permutation as concatenation of B decreasing blocks.
        // If block count is B and maximum block size is A, then:
        // - LIS equals number of blocks = B? Actually with this arrangement of increasing block values,
        //   LIS becomes number of blocks, LDS becomes max block size.
        // So to get LIS=A and LDS=B, we instead use A blocks, each decreasing,
        // with each block size <= B, and total N.
        //
        // Then:
        // - Since values in later blocks are larger than all values in earlier blocks,
        //   LIS = number of blocks = A.
        // - Each block is decreasing, so LDS = max block size = B.
        //
        // Need A block sizes:
        //   each >=1, each <=B, sum = N, and at least one equals B.
        // Start with all 1's, remaining = N-A.
        // Distribute up to B-1 extra per block.
        int[] sz = new int[A];
        Arrays.fill(sz, 1);
        int rem = N - A;
        for (int i = 0; i < A; i++) {
            int add = Math.min(rem, B - 1);
            sz[i] += add;
            rem -= add;
        }

        StringBuilder sb = new StringBuilder();
        int cur = 1;
        for (int i = 0; i < A; i++) {
            int l = cur;
            int r = cur + sz[i] - 1;
            for (int x = r; x >= l; x--) {
                sb.append(x).append(' ');
            }
            cur = r + 1;
        }

        System.out.println(sb.toString().trim());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

